import { expect, test } from 'vitest'
import { CapRoverClient } from '../src/clients/caprover'
import { RawApiClient } from '../src/clients/raw-api'
import { loadConfig } from '../src/config'

const config = loadConfig()

test('login validation, authorization, and SDK server-error propagation', async () => {
    const client = new CapRoverClient(
        config.caproverUrl,
        config.caproverPassword
    )
    const wrong = new CapRoverClient(config.caproverUrl, 'e2e-invalid-password')
    const raw = new RawApiClient(config.caproverUrl)
    try {
        await client.login()
        // These validations return before the server increments its failed-login counter.
        for (const password of ['', 'x'.repeat(30)]) {
            const response = await raw.request('POST', '/login', { password })
            expect(response.status).toBe(1000)
            expect(response.description).not.toBe('')
        }
        const unauthenticated = await raw.request(
            'GET',
            '/user/apps/appDefinitions'
        )
        expect(unauthenticated.status).toBe(1106)
        // One wrong-password attempt per run; no retries or brute-force/backoff test.
        await expect(wrong.login()).rejects.toMatchObject({
            captainStatus: 1105,
            captainMessage: 'Invalid credentials',
        })
    } finally {
        client.destroy()
        wrong.destroy()
    }
})

import { expect, test, vi } from 'vitest'
import { RawApiClient } from '../../src/clients/raw-api'

test('HTTP failures retain their status without trying to parse a JSON envelope', async () => {
    vi.stubGlobal(
        'fetch',
        vi
            .fn()
            .mockResolvedValue(
                new Response('Internal Server Error', { status: 500 })
            )
    )
    try {
        await expect(
            new RawApiClient('https://example.test').request(
                'POST',
                '/test',
                {}
            )
        ).rejects.toMatchObject({ httpStatus: 500 })
    } finally {
        vi.unstubAllGlobals()
    }
})

test('JSON API errors retain the server envelope', async () => {
    const envelope = { status: 1108, description: 'Invalid input' }
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(Response.json(envelope)))
    try {
        expect(
            await new RawApiClient('https://example.test').request(
                'POST',
                '/test',
                {}
            )
        ).toEqual(envelope)
    } finally {
        vi.unstubAllGlobals()
    }
})

test('additional headers are sent without replacing authenticated API headers', async () => {
    const fetch = vi
        .fn()
        .mockResolvedValueOnce(
            Response.json({
                status: 100,
                description: 'OK',
                data: { token: '[REDACTED]' },
            })
        )
        .mockResolvedValueOnce(
            Response.json({ status: 100, description: 'OK' })
        )
    vi.stubGlobal('fetch', fetch)
    const client = new RawApiClient('https://example.test')
    try {
        await client.login('password')
        await client.request(
            'POST',
            '/test',
            {},
            {
                'x-captain-app-token': 'app-token',
                'x-captain-auth': 'untrusted-token',
                'x-namespace': 'untrusted-namespace',
            }
        )

        expect(fetch).toHaveBeenLastCalledWith(
            'https://example.test/api/v2/test',
            expect.objectContaining({
                headers: expect.objectContaining({
                    'x-captain-app-token': 'app-token',
                    'x-captain-auth': expect.any(String),
                    'x-namespace': 'captain',
                    'Content-Type': 'application/json',
                }),
            })
        )
        expect(
            (fetch.mock.calls[1][1] as RequestInit).headers
        ).not.toMatchObject({ 'x-captain-auth': 'untrusted-token' })
    } finally {
        vi.unstubAllGlobals()
    }
})

import { randomBytes } from 'node:crypto'
import { expect, test } from 'vitest'
import { RawApiClient } from '../src/clients/raw-api'
import { loadConfig } from '../src/config'
import {
    nextVersion,
    waitForDeployment,
    waitForImage,
    waitForServiceStable,
    withDeploymentDiagnostics,
} from '../src/helpers/deployment'
import { createTestNames } from '../src/helpers/names'
import { eventually } from '../src/helpers/retry'
import { cleanUpApp, withTestContext } from '../src/helpers/test-context'

const FIRST_IMAGE =
    'nginx:1.28.3-alpine@sha256:a8b39bd9cf0f83869a2162827a0caf6137ddf759d50a171451b335cecc87d236'
const SECOND_IMAGE =
    'nginx:1.29.8-alpine@sha256:5616878291a2eed594aee8db4dade5878cf7edcb475e59193904b198d9b830de'

test('attached and detached deployment, controlled failure, missing image, and recovery', async () => {
    await withTestContext(async (context, cleanup, rootDomain) => {
        const { initialAppName: name, runId } = createTestNames()
        const api = context.caprover
        cleanUpApp(context, cleanup, name)
        await api.createApp(name)
        await waitForServiceStable(context, name)
        await withDeploymentDiagnostics(context, name, async () => {
            const url = `http://${name}.${rootDomain}`
            const before = await api.getApp(name)
            const gitHash = randomBytes(20).toString('hex')
            await api.deployDefinition(
                name,
                { schemaVersion: 2, imageName: FIRST_IMAGE },
                gitHash
            )
            let app = await waitForDeployment(
                context,
                name,
                nextVersion(before),
                gitHash
            )
            expect(app.deployedVersion).toBe(before.deployedVersion + 1)
            expect(
                app.versions.find(
                    (item) => item.version === app.deployedVersion
                )?.deployedImageName
            ).toBe(FIRST_IMAGE)
            await waitForImage(context, name, FIRST_IMAGE)
            await context.http.waitUntilReachable(url, 'Welcome to nginx!')

            const config = loadConfig()
            const raw = new RawApiClient(config.caproverUrl)
            await raw.login(config.caproverPassword)
            const detachedHash = randomBytes(20).toString('hex')
            const expectedVersion = nextVersion(app)
            const response = await raw.request(
                'POST',
                `/user/apps/appData/${name}?detached=1`,
                {
                    captainDefinitionContent: JSON.stringify({
                        schemaVersion: 2,
                        imageName: SECOND_IMAGE,
                    }),
                    gitHash: detachedHash,
                }
            )
            expect(response.status).toBe(101)
            app = await waitForDeployment(
                context,
                name,
                expectedVersion,
                detachedHash
            )
            expect(
                app.versions.find(
                    (item) => item.version === app.deployedVersion
                )?.deployedImageName
            ).toBe(SECOND_IMAGE)
            await waitForImage(context, name, SECOND_IMAGE)
            await context.http.waitUntilReachable(url, 'Welcome to nginx!')
            const workingVersion = app.deployedVersion

            const marker = `intentional-failure-${runId}`
            await api.deployDefinition(
                name,
                {
                    schemaVersion: 2,
                    dockerfileLines: [
                        `FROM ${SECOND_IMAGE}`,
                        `RUN echo ${marker} && exit 42`,
                    ],
                },
                randomBytes(20).toString('hex'),
                true
            )
            await eventually(
                async () => {
                    const build = await api.getBuildLogs(name)
                    expect(build.isAppBuilding).toBe(false)
                    expect(build.isBuildFailed).toBe(true)
                    expect(build.logs.lines.join('\n')).toContain(marker)
                },
                { timeoutMs: 90_000, description: 'controlled build failure' }
            )
            expect((await api.getApp(name)).deployedVersion).toBe(
                workingVersion
            )
            await waitForImage(context, name, SECOND_IMAGE)
            await context.http.waitUntilReachable(url, 'Welcome to nginx!')

            // A unique nonexistent tag in the same public repository; transport failures do not count.
            const missing = `nginx:caprover-e2e-missing-${runId}`
            await api.deployDefinition(
                name,
                { schemaVersion: 2, imageName: missing },
                randomBytes(20).toString('hex'),
                true
            )
            await eventually(
                async () => {
                    const build = await api.getBuildLogs(name)
                    expect(build.isAppBuilding).toBe(false)
                    expect(build.isBuildFailed).toBe(true)
                    const logs = build.logs.lines.join('\n')
                    expect(logs).toContain(missing)
                    const missingManifest =
                        /manifest unknown|manifest.*not found/i.test(logs)
                    const missingReference =
                        logs.includes('(HTTP code 404)') &&
                        logs.includes('failed to resolve reference') &&
                        logs.includes(`${missing}: not found`)
                    expect(missingManifest || missingReference).toBe(true)
                },
                { timeoutMs: 90_000, description: 'missing-image rejection' }
            )
            expect((await api.getApp(name)).deployedVersion).toBe(
                workingVersion
            )
            await waitForImage(context, name, SECOND_IMAGE)
            await context.http.waitUntilReachable(url, 'Welcome to nginx!')

            const recoveryVersion = nextVersion(await api.getApp(name))
            const recoveryHash = randomBytes(20).toString('hex')
            await api.deployDefinition(
                name,
                { schemaVersion: 2, imageName: FIRST_IMAGE },
                recoveryHash
            )
            await waitForDeployment(
                context,
                name,
                recoveryVersion,
                recoveryHash
            )
            await waitForImage(context, name, FIRST_IMAGE)
            await context.http.waitUntilReachable(url, 'Welcome to nginx!')
        })
    })
})

import { expect, test } from 'vitest'
import { SshClient, SshCommandResult } from '../../src/clients/ssh'
import { loadConfig } from '../../src/config'
import type { TestContext } from '../../src/context'
import {
    nextVersion,
    waitForDeployment,
    waitForImage,
    waitForServiceStable,
} from '../../src/helpers/deployment'
import { createTestNames } from '../../src/helpers/names'
import { eventually } from '../../src/helpers/retry'
import { sourceArchive } from '../../src/helpers/source-fixture'
import { cleanUpApp, withTestContext } from '../../src/helpers/test-context'
import { DockerInspector } from '../../src/inspectors/docker'
import { requireEphemeral } from '../../src/test-selection'

const FIRST_IMAGE =
    'nginx:1.28.3-alpine@sha256:a8b39bd9cf0f83869a2162827a0caf6137ddf759d50a171451b335cecc87d236'
const SECOND_IMAGE =
    'nginx:1.29.8-alpine@sha256:5616878291a2eed594aee8db4dade5878cf7edcb475e59193904b198d9b830de'
const VOLUME_PATH = '/e2e-data'

test('a worker runs pinned stateless and persistent applications', async () => {
    requireEphemeral()
    const config = loadConfig()
    if (!config.workerIpAddress) {
        throw new Error(
            'Multi-node tests require E2E_WORKER_IP from E2E_PROVISION_WORKER=true provisioning'
        )
    }

    const workerSsh = new SshClient({
        host: config.workerIpAddress,
        port: 22,
        username: 'root',
        privateKey: [REDACTED],
        commandTimeoutMs: 30_000,
    })
    const workerDocker = new DockerInspector(workerSsh)

    await workerSsh.connect()
    try {
        await withTestContext(async (context, cleanup, rootDomain) => {
            const { runId } = createTestNames()
            const compactId = runId.replaceAll('-', '')
            const statelessApp = `node-${compactId}-s`
            const persistentApp = `node-${compactId}-p`
            const volumeName = `e2e-${runId}-worker-volume`
            const sourceMarker = `worker-source-${runId}`
            const volumeMarker = `worker-volume-${runId}`
            let workerNodeId: string | undefined

            expect(new URL(config.caproverUrl).protocol).toBe('https:')
            expect(await context.caprover.getServerInfo()).toMatchObject({
                hasRootSsl: true,
                forceSsl: true,
            })
            expect(await context.docker.getNodes()).toHaveLength(1)

            cleanup.add(async () => {
                await removeWorkerNode(context, workerSsh, workerNodeId)
            })
            cleanup.add(async () => {
                await disableLocalRegistry(context)
            })

            const registry = await enableDefaultLocalRegistry(context)
            await context.caprover.addDockerNode(
                'worker',
                config.sshPrivateKey,
                config.workerIpAddress!,
                '22',
                'root',
                config.sshHost
            )

            workerNodeId = await eventually(
                async () => {
                    const workerLocalNodeId =
                        await workerDocker.getLocalNodeId()
                    const apiNodes = (await context.caprover.getAllNodes())
                        .nodes
                    const worker = apiNodes.find(
                        (node) => node.nodeId === workerLocalNodeId
                    )
                    expect(worker).toMatchObject({
                        nodeId: workerLocalNodeId,
                        type: 'worker',
                        ip: config.workerIpAddress,
                        state: 'ready',
                        status: 'active',
                    })

                    const dockerNodes = await context.docker.getNodes()
                    expect(dockerNodes).toHaveLength(2)
                    expect(
                        dockerNodes.find(
                            (node) => node.ID === workerLocalNodeId
                        )
                    ).toMatchObject({
                        ID: workerLocalNodeId,
                        Spec: { Role: 'worker', Availability: 'active' },
                        Status: {
                            Addr: config.workerIpAddress,
                            State: 'ready',
                        },
                    })
                    return workerLocalNodeId
                },
                {
                    timeoutMs: 90_000,
                    description: 'worker registration in CapRover and Swarm',
                }
            )

            cleanUpApp(context, cleanup, statelessApp)
            await context.caprover.createApp(statelessApp)
            await waitForServiceStable(context, statelessApp)
            await context.caprover.updateApp(statelessApp, {
                nodeId: workerNodeId,
            })
            await assertWorkerPlacement(context, statelessApp, workerNodeId)
            const sourceVersion = nextVersion(
                await context.caprover.getApp(statelessApp)
            )
            await context.caprover.uploadSource(
                statelessApp,
                await sourceArchive(sourceMarker),
                false
            )
            const sourceApp = await waitForDeployment(
                context,
                statelessApp,
                sourceVersion
            )
            const sourceImage = sourceApp.versions.find(
                (version) => version.version === sourceVersion
            )?.deployedImageName
            expect(sourceImage).toBe(
                `${registry.registryDomain}/${registry.registryImagePrefix}/img-captain-${statelessApp}:${sourceVersion}`
            )
            await waitForImage(context, statelessApp, sourceImage!)
            await assertWorkerPlacement(context, statelessApp, workerNodeId)
            await context.http.waitUntilReachable(
                `http://${statelessApp}.${rootDomain}`,
                sourceMarker,
                60_000
            )

            cleanup.add(async () => {
                await eventually(
                    async () => {
                        await workerDocker.removeVolume(volumeName)
                        expect(
                            await workerDocker.volumeExists(volumeName)
                        ).toBe(false)
                    },
                    { description: `worker volume ${volumeName} deletion` }
                )
            })
            cleanUpApp(context, cleanup, persistentApp)
            await context.caprover.createPersistentApp(persistentApp)
            await context.caprover.updateApp(persistentApp, {
                nodeId: workerNodeId,
                volumes: [{ volumeName, containerPath: VOLUME_PATH }],
            })
            await assertWorkerPlacement(context, persistentApp, workerNodeId)
            expect(
                await context.docker.getServiceVolumeSources(persistentApp)
            ).toEqual([volumeName])
            expect(await workerDocker.volumeExists(volumeName)).toBe(true)
            await context.caprover.deployImage(persistentApp, FIRST_IMAGE)
            await waitForImage(context, persistentApp, FIRST_IMAGE)
            await assertWorkerPlacement(context, persistentApp, workerNodeId)
            expect(
                await context.docker.getServiceVolumeSources(persistentApp)
            ).toEqual([volumeName])
            expect(await workerDocker.volumeExists(volumeName)).toBe(true)
            await workerDocker.writeVolumeMarker(volumeName, volumeMarker)
            const firstTaskIds =
                await context.docker.getRunningTaskIds(persistentApp)
            expect(firstTaskIds).toHaveLength(1)

            await context.caprover.deployImage(persistentApp, SECOND_IMAGE)
            await waitForImage(context, persistentApp, SECOND_IMAGE)
            await assertWorkerPlacement(context, persistentApp, workerNodeId)
            const secondTaskIds =
                await context.docker.getRunningTaskIds(persistentApp)
            expect(secondTaskIds).toHaveLength(1)
            expect(secondTaskIds[0]).not.toBe(firstTaskIds[0])
            expect(await workerDocker.readVolumeMarker(volumeName)).toBe(
                volumeMarker
            )

            await context.caprover.deleteApp(statelessApp)
            await context.caprover.deleteApp(persistentApp)
            await eventually(async () => {
                expect(await context.caprover.appExists(statelessApp)).toBe(
                    false
                )
                expect(await context.caprover.appExists(persistentApp)).toBe(
                    false
                )
                expect(await context.docker.serviceExists(statelessApp)).toBe(
                    false
                )
                expect(await context.docker.serviceExists(persistentApp)).toBe(
                    false
                )
            })
            await eventually(
                async () => {
                    await workerDocker.removeVolume(volumeName)
                    expect(await workerDocker.volumeExists(volumeName)).toBe(
                        false
                    )
                },
                { description: `worker volume ${volumeName} deletion` }
            )

            await disableLocalRegistry(context)
            await removeWorkerNode(context, workerSsh, workerNodeId)
            await eventually(async () => {
                expect(
                    (await context.caprover.getAllNodes()).nodes
                ).toHaveLength(1)
                expect(await context.docker.getNodes()).toHaveLength(1)
            })
        })
    } finally {
        workerSsh.close()
    }
}, 720_000)

async function enableDefaultLocalRegistry(context: TestContext) {
    const api = context.caprover
    const initial = await api.getDockerRegistries()
    expect(
        initial.registries.some(
            (registry) => registry.registryType === 'LOCAL_REG'
        )
    ).toBe(false)

    await api.enableSelfHostedDockerRegistry()
    const local = await eventually(
        async () => {
            const current = await api.getDockerRegistries()
            const candidate = current.registries.find(
                (registry) => registry.registryType === 'LOCAL_REG'
            )
            expect(candidate).toBeDefined()
            return candidate!
        },
        {
            timeoutMs: 60_000,
            description: 'self-hosted registry API entry',
        }
    )
    await waitForServiceStable(context, 'captain-registry')
    await api.setDefaultPushDockerRegistry(local.id)
    expect((await api.getDockerRegistries()).defaultPushRegistryId).toBe(
        local.id
    )
    return local
}

async function disableLocalRegistry(context: TestContext): Promise<void> {
    const current = await context.caprover.getDockerRegistries()
    const local = current.registries.find(
        (registry) => registry.registryType === 'LOCAL_REG'
    )
    if (!local) return
    if (current.defaultPushRegistryId === local.id) {
        await context.caprover.setDefaultPushDockerRegistry('')
    }
    await context.caprover.disableSelfHostedDockerRegistry()
    await eventually(async () => {
        expect(
            (await context.caprover.getDockerRegistries()).registries.some(
                (registry) => registry.registryType === 'LOCAL_REG'
            )
        ).toBe(false)
        expect(await context.docker.serviceExists('captain-registry')).toBe(
            false
        )
    })
}

async function assertWorkerPlacement(
    context: TestContext,
    appName: string,
    workerNodeId: string
): Promise<void> {
    expect((await context.caprover.getApp(appName)).nodeId).toBe(workerNodeId)
    await eventually(
        async () => {
            expect(
                await context.docker.getServicePlacementConstraints(appName)
            ).toContain(`node.id == ${workerNodeId}`)
            expect(await context.docker.getRunningTaskNodeIds(appName)).toEqual(
                [workerNodeId]
            )
            await waitForServiceStable(context, appName)
        },
        {
            timeoutMs: 90_000,
            description: `${appName} placement on the worker`,
        }
    )
}

async function removeWorkerNode(
    context: TestContext,
    workerSsh: SshClient,
    workerNodeId: string | undefined
): Promise<void> {
    const failures: Error[] = []
    let nodeId = workerNodeId
    if (!nodeId) {
        try {
            const info = await workerSsh.exec(
                "docker info --format '{{.Swarm.NodeID}}'"
            )
            if (info.exitCode === 0 && info.stdout.trim()) {
                nodeId = info.stdout.trim()
            }
        } catch (error) {
            failures.push(asError(error))
        }
    }

    try {
        const leave = await workerSsh.exec('docker swarm leave')
        if (leave.exitCode !== 0 && !isAlreadyOutsideSwarm(leave)) {
            failures.push(commandError('worker swarm leave', leave))
        }
    } catch (error) {
        failures.push(asError(error))
    }

    if (nodeId) {
        if (!/^[a-z0-9]{25}$/.test(nodeId)) {
            failures.push(new Error(`Unsafe Docker node ID: ${nodeId}`))
        } else {
            try {
                await eventually(
                    async () => {
                        const result = await context.ssh.exec(
                            `docker node rm --force '${nodeId}'`
                        )
                        if (result.exitCode !== 0 && !isMissingNode(result)) {
                            throw commandError('manager node removal', result)
                        }
                        expect(
                            (await context.docker.getNodes()).some(
                                (node) => node.ID === nodeId
                            )
                        ).toBe(false)
                    },
                    {
                        timeoutMs: 45_000,
                        description: 'worker Swarm node removal',
                    }
                )
            } catch (error) {
                failures.push(asError(error))
            }
        }
    }

    if (failures.length) {
        throw new AggregateError(failures, 'Failed to remove worker node')
    }
}

function isAlreadyOutsideSwarm(result: SshCommandResult): boolean {
    return `${result.stdout}\n${result.stderr}`
        .toLowerCase()
        .includes('not part of a swarm')
}

function isMissingNode(result: SshCommandResult): boolean {
    return /no such node|node .+ not found/i.test(
        `${result.stdout}\n${result.stderr}`
    )
}

function commandError(description: string, result: SshCommandResult): Error {
    return new Error(
        `${description} failed with exit code ${result.exitCode}: ${result.stderr || result.stdout}`
    )
}

function asError(error: unknown): Error {
    return error instanceof Error ? error : new Error(String(error))
}

import CapRoverAPI, {
    CapRoverModels,
    SimpleAuthenticationProvider,
} from 'caprover-api'
import { expect, test } from 'vitest'
import { RawApiClient } from '../../src/clients/raw-api'
import { loadConfig } from '../../src/config'
import { totpFromUri } from '../../src/helpers/totp'
import { withTestContext } from '../../src/helpers/test-context'
import { requireEphemeral } from '../../src/test-selection'

test('a dedicated Pro key enables 2FA and requires TOTP at login', async () => {
    requireEphemeral()
    const apiKey = [REDACTED]
    if (!apiKey) throw new Error('E2E_PRO_API_KEY is required for Pro tests')

    const config = loadConfig()
    if (new URL(config.caproverUrl).protocol !== 'https:') {
        throw new Error('Pro and 2FA tests require E2E_ENABLE_HTTPS=true')
    }

    await withTestContext(async (context, cleanup) => {
        const api = context.caprover
        expect((await api.getProFeaturesState()).isSubscribed).toBe(false)
        expect((await api.getOtpStatus()).isEnabled).toBe(false)

        await api.setProApiKey(apiKey)
        expect(await api.getProFeaturesState()).toMatchObject({
            isSubscribed: true,
            isFeatureFlagEnabled: true,
        })

        const initialConfigs = await api.getProConfigs()
        cleanup.add(async () => {
            await api.setProConfigs(initialConfigs)
            expect(await api.getProConfigs()).toEqual(initialConfigs)
        })
        const proConfigs = {
            alerts: [
                {
                    event: CapRoverModels.ProAlertEvent.AppBuildFailed,
                    action: {
                        actionType: CapRoverModels.ProAlertActionType.email,
                    },
                },
            ],
        }
        await api.setProConfigs(proConfigs)
        expect(await api.getProConfigs()).toEqual(proConfigs)

        // The backend stores the 2FA flag on this disposable CapRover server.
        // Register cleanup before the first attempt to enable it.
        cleanup.add(async () => {
            if ((await api.getOtpStatus()).isEnabled) {
                await api.setOtpStatus({ enabled: false })
            }
            expect((await api.getOtpStatus()).isEnabled).toBe(false)
        })

        const setup = await api.setOtpStatus({ enabled: true })
        expect(setup.isEnabled).toBe(false)
        const otpPath = setup.otpPath
        if (!otpPath) throw new Error('Pro did not return a TOTP URI')

        const otp = totpFromUri(otpPath)
        expect(await api.setOtpStatus({ enabled: true, token: otp })).toEqual({
            isEnabled: true,
        })
        expect((await api.getOtpStatus()).isEnabled).toBe(true)

        const raw = new RawApiClient(config.caproverUrl)
        expect(
            await raw.request('POST', '/login', {
                password: [REDACTED],
            })
        ).toMatchObject({ status: 1114 })

        const provider = new SimpleAuthenticationProvider(async () => ({
            password: [REDACTED],
            otpToken: [REDACTED],
        }))
        const otpClient = new CapRoverAPI(config.caproverUrl, provider)
        try {
