            expect(
                await context.docker.getServiceVolumeSources(sharedApp)
            ).toEqual([volumeName])
            expect(await context.docker.getRunningReplicas(sharedApp)).toBe(1)
        })
        const partialDelete = await context.caprover.deleteApp(firstApp, [
            volumeName,
        ])
        expect(partialDelete.volumesFailedToDelete).toEqual([volumeName])
        expect(await context.docker.volumeExists(volumeName)).toBe(true)

        await context.caprover.deleteApp(sharedApp, [volumeName])
        await eventually(
            async () => {
                expect(await context.docker.serviceExists(sharedApp)).toBe(
                    false
                )
                expect(await context.docker.volumeExists(volumeName)).toBe(
                    false
                )
            },
            {
                timeoutMs: 30_000,
                description: `owned volume ${volumeName} removal`,
            }
        )

        cleanUpApp(context, cleanup, nonPersistentApp)
        await context.caprover.createApp(nonPersistentApp)
        await expect(
            context.caprover.updateApp(nonPersistentApp, { volumes: [volume] })
        ).rejects.toMatchObject({ captainStatus: 1108 })

        cleanUpApp(context, cleanup, firstApp)
        await context.caprover.createPersistentApp(firstApp)
        for (const invalid of [
            { volumeName, containerPath: '' },
            { volumeName: '', containerPath: CONTAINER_PATH },
            { volumeName: '-invalid', containerPath: CONTAINER_PATH },
        ]) {
            await expect(
                context.caprover.updateApp(firstApp, { volumes: [invalid] })
            ).rejects.toMatchObject({ captainStatus: 1000 })
            expect((await context.caprover.getApp(firstApp)).volumes).toEqual(
                []
            )
        }
    })
})

import { execFile as execFileCallback } from 'node:child_process'
import { randomUUID } from 'node:crypto'
import { mkdtemp, rm, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { promisify } from 'node:util'
import { expect, test } from 'vitest'
import { loadConfig } from '../src/config'
import { createTestNames } from '../src/helpers/names'
import { eventually } from '../src/helpers/retry'
import { cleanUpApp, withTestContext } from '../src/helpers/test-context'
import { requireEphemeral } from '../src/test-selection'

const execFile = promisify(execFileCallback)

test('backup download is inspectable, contains owned configuration, and is one-time', async () => {
    requireEphemeral()
    await withTestContext(async (context, cleanup) => {
        const { initialAppName: appName } = createTestNames()
        const marker = `backup-${randomUUID()}`
        cleanUpApp(context, cleanup, appName)
        await context.caprover.createApp(appName)
        await context.caprover.updateApp(appName, { description: marker })
        expect((await context.caprover.getApp(appName)).description).toBe(
            marker
        )

        const { downloadToken } = await context.caprover.createBackup()
        expect(downloadToken.length).toBeGreaterThan(0)
        const downloadUrl = backupUrl(downloadToken)

        const invalid = await context.http.getBinary(
            backupUrl(`${downloadToken}x`)
        )
        expect(invalid.status).toBe(200)
        expect(isTarArchive(invalid)).toBe(false)
        expect(parseEnvelopeStatus(invalid.body)).toBe(1106)

        const archive = await context.http.getBinary(downloadUrl)
        expect(archive.status).toBeGreaterThanOrEqual(200)
        expect(archive.status).toBeLessThan(300)
        expect(archive.body.length).toBeGreaterThan(0)
        expect(archive.headers.get('content-disposition')).toContain(
            'caprover-backup-'
        )
        expect(isTarArchive(archive)).toBe(true)

        const directory = await mkdtemp(join(tmpdir(), 'caprover-e2e-backup-'))
        try {
            const archivePath = join(directory, 'backup.tar')
            await writeFile(archivePath, archive.body)
            const entries = await tarList(archivePath)
            expect(entries).toContain('meta/backup.json')
            expect(entries).toContain('data/config-captain.json')
            expect(entries).not.toContain('data/data/config-captain.json')

            const meta = JSON.parse(
                await tarRead(archivePath, 'meta/backup.json')
            ) as { nodes?: Array<{ nodeId?: string }>; salt?: string }
            expect(meta.nodes?.length).toBeGreaterThan(0)
            expect(new Set(meta.nodes?.map((node) => node.nodeId))).toEqual(
                new Set(
                    (await context.caprover.getAllNodes()).nodes.map(
                        (node) => node.nodeId
                    )
                )
            )
            expect(typeof meta.salt).toBe('string')
            expect(meta.salt?.length).toBeGreaterThan(0)

            const config = JSON.parse(
                await tarRead(archivePath, 'data/config-captain.json')
            ) as {
                appDefinitions?: Record<string, { description?: string }>
            }
            expect(config.appDefinitions?.[appName]?.description).toBe(marker)
        } finally {
            await rm(directory, { recursive: true, force: true })
        }

        await eventually(
            async () => {
                const repeated = await context.http.getBinary(downloadUrl)
                expect(isTarArchive(repeated)).toBe(false)
                expect(repeated.status).toBe(404)
            },
            { description: 'one-time backup download to become unavailable' }
        )
    })
})

function backupUrl(downloadToken: string): string {
    const url = new URL('/api/v2/downloads/', loadConfig().caproverUrl)
    url.searchParams.set('namespace', 'captain')
    url.searchParams.set('downloadToken', downloadToken)
    return url.toString()
}

function isTarArchive(response: { status: number; headers: Headers }): boolean {
    return (
        response.status >= 200 &&
        response.status < 300 &&
        response.headers.get('content-disposition')?.includes('.tar') === true
    )
}

function parseEnvelopeStatus(body: Buffer): number | undefined {
    try {
        const value = JSON.parse(body.toString('utf8')) as { status?: unknown }
        return typeof value.status === 'number' ? value.status : undefined
    } catch {
        return undefined
    }
}

async function tarList(archivePath: string): Promise<string[]> {
    const { stdout } = await execFile('tar', ['-tf', archivePath])
    return stdout
        .split(/\r?\n/)
        .map((entry) => entry.replace(/^\.\//, ''))
        .filter(Boolean)
}

async function tarRead(archivePath: string, entry: string): Promise<string> {
    const { stdout } = await execFile('tar', ['-xOf', archivePath, entry])
    return stdout
}

export interface ApiEnvelope<T = unknown> {
    status: number
    description: string
    data?: T
}

// Used only for wire-level contracts that the SDK unwraps or automatically retries.
export class RawApiClient {
    private token = ''
    constructor(private readonly baseUrl: string) {}

    async login(password: string): Promise<void> {
        const result = await this.request<{ token: string }>('POST', '/login', {
            password,
        })
        if (result.status !== 100 || !result.data?.token) {
            throw new Error(`Raw API login failed with status ${result.status}`)
        }
        this.token = [REDACTED]
    }

    async request<T = unknown>(
        method: 'GET' | 'POST' | 'PATCH',
        path: string,
        body?: unknown,
        additionalHeaders: Record<string, string> = {}
    ): Promise<ApiEnvelope<T>> {
        const multipart = body instanceof FormData
        const response = await fetch(`${this.baseUrl}/api/v2${path}`, {
            method,
            headers: {
                ...additionalHeaders,
                'x-namespace': 'captain',
                ...(multipart ? {} : { 'Content-Type': 'application/json' }),
                ...(this.token ? { 'x-captain-auth': this.token } : {}),
            },
            body:
                body === undefined
                    ? undefined
                    : multipart
                      ? body
                      : JSON.stringify(body),
            signal: AbortSignal.timeout(30_000),
            redirect: 'error',
        })
        if (!response.ok)
            throw Object.assign(
                new Error(`Raw API request failed: HTTP ${response.status}`),
                { httpStatus: response.status }
            )
        return response.json() as Promise<ApiEnvelope<T>>
    }
}

import { expect } from 'vitest'
import { AppDefinition } from '../clients/caprover'
import { TestContext } from '../context'
import { eventually } from './retry'

export function nextVersion(app: AppDefinition): number {
    return Math.max(
        app.versions.length,
        ...app.versions.map((version) => version.version + 1)
    )
}

export async function waitForDeployment(
    context: TestContext,
    name: string,
    version: number,
    gitHash?: string
): Promise<AppDefinition> {
    return eventually(
        async () => {
            const [app, build] = await Promise.all([
                context.caprover.getApp(name),
                context.caprover.getBuildLogs(name),
            ])
            expect(build.isAppBuilding).toBe(false)
            expect(build.isBuildFailed).toBe(false)
            expect(app.deployedVersion).toBe(version)
            const entry = app.versions.find((item) => item.version === version)
            expect(entry?.deployedImageName).toBeTruthy()
            if (gitHash !== undefined) expect(entry?.gitHash).toBe(gitHash)
            return app
        },
        {
            timeoutMs: 90_000,
            description: `${name} deployment version ${version}`,
        }
    )
}

export async function waitForServiceStable(
    context: TestContext,
    name: string
): Promise<void> {
    await eventually(
        async () => {
            const desiredReplicas =
                await context.docker.getDesiredReplicas(name)
            expect(await context.docker.getRunningReplicas(name)).toBe(
                desiredReplicas
            )
            const updateState = await context.docker.getServiceUpdateState(name)
            expect(
                updateState === undefined || updateState === 'completed'
            ).toBe(true)
        },
        { timeoutMs: 45_000, description: `${name} service update to settle` }
    )
}

export async function waitForImage(
    context: TestContext,
    name: string,
    image: string
): Promise<void> {
    await eventually(
        async () => {
            expect(await context.docker.getDesiredReplicas(name)).toBe(1)
            expect(await context.docker.getRunningReplicas(name)).toBe(1)
            expect(
                context.docker.imageMatches(
                    await context.docker.getServiceImage(name),
                    image
                )
            ).toBe(true)
            const images = await context.docker.getRunningTaskImages(name)
            expect(images).toHaveLength(1)
            expect(
                images.every((actual) =>
                    context.docker.imageMatches(actual, image)
                )
            ).toBe(true)
            const updateState = await context.docker.getServiceUpdateState(name)
            expect(
                updateState === undefined || updateState === 'completed'
            ).toBe(true)
        },
        { timeoutMs: 45_000, description: `${name} running expected image` }
    )
}

export async function withDeploymentDiagnostics(
    context: TestContext,
    name: string,
    operation: () => Promise<void>
): Promise<void> {
    try {
        await operation()
    } catch (error) {
        // Only invoke for test-owned fixtures that never contain credentials.
        const build = await context.caprover
            .getBuildLogs(name)
            .catch(() => undefined)
        console.error(
            JSON.stringify({
                appName: name,
                build: build && {
                    isAppBuilding: build.isAppBuilding,
                    isBuildFailed: build.isBuildFailed,
                    lines: build.logs.lines.slice(-30).join('\n').slice(-6000),
                },
                docker: await context.docker.getDiagnostics(name),
            })
        )
        throw error
    }
}
